function potTxt(U,m){const P=POT[U.e];if(!P)return '';const pw=U.pw*(m||1);return P[0].replace(/\{p\}/g,Math.round(pw)).replace(/\{d\}/g,Math.round(pw*10)/10)+` · every ${U.cd}s`;}
function gearQ(it){return GEAR_Q[it&&it.q!=null?it.q:1];}
function gearName(it){const D=gearDef(it);if(!D)return '?';const q=gearQ(it).n;return (q?q+' ':'')+D.n;}
function newGear(id,rng,q){const D=GEAR_DB[id];rng=rng||Math.random;return {g:id,q:q!=null?q:1,ch:D.p.map(p=>p.lo+Math.floor(rng()*(p.hi-p.lo+1))),u:Math.floor(rng()*1e9)};}
function gearRoll(rng,luck,src,stage){rng=rng||Math.random;const L=Math.max(0,luck||0);const bump=src==='box'?2.2:src==='crate'?1.5:1;
  const PR=(CURG&&CURG.run&&CURG.run.prestige)||0;const W=GEAR_RAR.map((r,i)=>i===0?r.w:r.godly?(PR>0?.06*PR*bump:.003*bump):r.w*(1+L*.02)*bump*(1+.04*Math.max(0,(stage||1)-8)));const tot=W.reduce((a,b)=>a+b,0);let x=rng()*tot,ri=0;for(;ri<W.length-1;ri++){x-=W[ri];if(x<0)break;}
  const pool=GEAR_DB.filter(d=>d.r===ri);const D=pool[Math.floor(rng()*pool.length)]||GEAR_DB[0];
  const qr=rng();const q=qr<.35?0:qr<.9-L*.002?1:qr<.985?2:3;return newGear(D.id,rng,q);}
function gearSlot(slot){if(!slot)return null;slot.gear=slot.gear||{stash:[],eq:{}};slot.gear.stash=slot.gear.stash||[];slot.gear.eq=slot.gear.eq||{};return slot.gear;}
function gearOn(slot,k){const G=gearSlot(slot);if(!G)return {};return G.eq[k]=G.eq[k]||{};}
function gearStat(slot,k){const E=slot&&slot.gear&&slot.gear.eq&&slot.gear.eq[k];if(!E)return null;const o={};for(const s of GEAR_ALL){const it=E[s];const D=gearDef(it);if(!D)continue;const m=gearQ(it).m;
  for(const [x,v] of Object.entries(D.st))o[x]=(o[x]||0)+v*m;}return o;}
function gearProcs(slot,k){const E=slot&&slot.gear&&slot.gear.eq&&slot.gear.eq[k];const out=[];if(!E)return out;for(const s of GEAR_ALL){const it=E[s];const D=gearDef(it);if(!D)continue;const m=gearQ(it).m;
  D.p.forEach((p,i)=>out.push({t:p.t,e:p.e,ch:Math.min(60,((it.ch||[])[i]||p.lo)*m),it}));}return out;}
function gearEquip(slot,k,si,want){const G=gearSlot(slot);const it=G.stash[si];const D=gearDef(it);if(!D)return false;const SL=gearSlotsOf(k).map(x=>x[0]);let to=D.s;
  if(D.s==='P'&&k==='alchemist')to=want&&/^P/.test(want)?want:(['P','P2','P3'].find(x=>!gearOn(slot,k)[x])||'P');if(!SL.includes(to))return false;const E=gearOn(slot,k);G.stash.splice(si,1);if(E[to])G.stash.push(E[to]);E[to]=it;return true;}
function gearUnequip(slot,k,s){const G=gearSlot(slot);const E=gearOn(slot,k);if(!E[s])return false;if(G.stash.length>=GEAR_STASH)return false;G.stash.push(E[s]);E[s]=null;return true;}
function gearUpgrade(slot,it){if(!it||it.q>=3)return 'max';const c=GEAR_UPG[it.q];if((slot.parts||0)<c.p)return 'parts';if((slot.gold||0)<c.g)return 'gold';slot.parts-=c.p;slot.gold-=c.g;it.q++;return 'ok';}
