const GEAR_SELL=[3,6,15,35,80,200,500,1500];function gearPrice(it){const D=gearDef(it);if(!D)return 0;return Math.max(1,Math.round(GEAR_SELL[D.r]*[.6,1,1.4,2][it.q||0]));}
function gearSell(slot,si){const G=gearSlot(slot);const it=G.stash[si];if(!it)return 0;const v=gearPrice(it);G.stash.splice(si,1);slot.gold=(slot.gold||0)+v;return v;}
function gearSellTiers(slot,tiers){const G=gearSlot(slot);let gold=0,n=0;for(let i=G.stash.length-1;i>=0;i--){const D=gearDef(G.stash[i]);if(D&&tiers.includes(D.r)){gold+=gearSell(slot,i);n++;}}return {gold,n};}
function gearScrap(slot,si){const G=gearSlot(slot);const it=G.stash[si];if(!it)return 0;G.stash.splice(si,1);const v=1+Math.max(0,gearDef(it).r-1)+Math.max(0,it.q-1);slot.parts=(slot.parts||0)+v;return v;}
function gearTxt(it){const D=gearDef(it);if(!D)return {stats:[],procs:[]};const m=gearQ(it).m;const r1=x=>Math.round(x*10)/10;if(D.u){const T0=gearTxt0(it);T0.procs.unshift(potTxt(D.u,m));return T0;}return gearTxt0(it);}
