    for(const h of this.heroes){if(!h.alive)continue;const ph=(h.key.length*1.7)%6.3;const amp=this.scroll?3:7;
      h.wanderX=(h.defuse||h.search||(h.building&&h.walkTo==null)||h.repairing||(h.plan&&/^(search|disarm|portal|defuse)$/.test(h.plan.intent||'')))?0:Math.sin(this.t*1.1+ph)*amp+Math.sin(this.t*2.7+ph*2)*amp*.45;}   /* no idle sway while defusing or cutting an alarm */
