/* 0.12.335 (Kyle) TALENT TREES v2. Each branch: T1 3 picks · T2 3 picks · T3 choose 1 of 2 full capstones · T4 3 picks · T5 3 picks · T6 choose 1 of 2
   capstones. 12 capstones per hero. Rows open at 0/3/6/7/10/13 points spent in that branch.
   - the LEFT capstone needs at least 1 point in the left or middle talent right above it; the RIGHT capstone needs the middle or right one
   - only one capstone per tier; taking a T3 capstone locks the far-side T4 talent under it (left cap locks T4 right, right cap locks T4 left)
   - T4/T5 talents carry 2+ effects each. Every effect is real numbers on the hero or an ability (nothing is text-only). */
const TREES={};
const TREE_FILL={hp:['Iron Gut','🫀',{st:{hpPct:4}}],armor:['Scar Tissue','🩹',{st:{mod:{armor:1}}}],crit:['Keen Eye','👁️',{st:{mod:{crit:2}}}],move:['Light Feet','🪶',{st:{mod:{move:3}}}],
  dmg:['Mean Streak','😤',{st:{dmgPct:3}}],regen:['Deep Breaths','🌬️',{st:{mod:{enRegen:.3}}}],acc:['Steady Hands','🎯',{st:{mod:{acc:2}}}],kb:['Planted','🧱',{st:{mod:{kbRes:8}}}],
  enmax:['Big Lungs','🎈',{st:{mod:{enMax:6}}}],luck:['Lucky Charm','🍀',{st:{mod:{luck:2}}}]};
const TREE_FILL_NAMES={hp:['Iron Gut','Thick Blood','Hard to Kill','Tough as Nails','Stubborn'],armor:['Scar Tissue','Callused','Padded','Hide Like Leather','Battered'],
  crit:['Keen Eye','Weak Spots','Cold Read','Sharp Sight','Precision'],move:['Light Feet','Quick Step','Fleet','Nimble','Spry'],dmg:['Mean Streak','Bad Attitude','Heavy Hands','Grit','Vicious'],
  regen:['Deep Breaths','Steady Breathing','Pacing','Calm Mind','Rhythm'],acc:['Steady Hands','Dead Aim','Focus','Patience','Bead On It'],kb:['Planted','Rooted','Low Center','Anchor','Unmovable'],
  enmax:['Big Lungs','Reserve Tank','Stamina','Deep Well','Fuel'],luck:['Lucky Charm','Rabbit Foot','Fortune','Horseshoe','Good Omen']};
const TREE_FILL_ORDER=[['regen','crit','hp','move','acc'],['armor','dmg','kb','enmax','luck'],['hp','dmg','crit','armor','regen'],['move','luck','acc','enmax','kb']];
function treeStatKeys(e){const o=[];if(e&&e.st){const S=e.st;if(S.hpPct)o.push('hp');if(S.dmgPct)o.push('dmg');for(const x of Object.keys(S.mod||{}))o.push({armor:'armor',crit:'crit',move:'move',enRegen:'regen',acc:'acc',kbRes:'kb',enMax:'enmax',luck:'luck'}[x]||x);}return o;}
/* 0.12.423 (Kyle): the old capstones now sit on row 6 under an ultimate, so they keep 60% of what they used to add.
   Card numbers move 60% of the way from the hero's normal value; card text is rewritten with the new numbers. */
const CAP6=.6;
function effNerf(e){const o=JSON.parse(JSON.stringify(e));for(const g of ['mul','add'])for(const f of Object.keys(o[g]||{}))o[g][f]=Math.round(o[g][f]*CAP6*1000)/1000;if(o.face)o.face=Math.max(1,Math.round(o.face*CAP6));return o;}
function capNerf(k,tal){const [t,L,b]=tal.split(':');if(t!=='cap')return tal;const C=HCAP[k]&&HCAP[k][L]&&HCAP[k][L][b];if(!C)return tal;const nb=b+'_r6';if(HCAP[k][L][nb])return 'cap:'+L+':'+nb;
  const N=JSON.parse(JSON.stringify(C));N.src=b;let txt=C.txt||'';const swaps=[];
  const fmtN=(v,int)=>int?String(Math.round(v)):String(Math.round(v*100)/100);
  const sub=(from,to)=>{if(from===to)return;const i=txt.indexOf(from);if(i<0)return;txt=txt.slice(0,i)+'\u0000'+swaps.length+'\u0000'+txt.slice(i+from.length);swaps.push(to);};
  const CH=CHAR[k]||{};
  for(const P of N.patch||[]){const A0=P.ab==='_melee'?CH.melee:P.ab==='_ranged'?CH.ranged:(CH.abilities||[]).find(a=>a.id===P.ab);const A=A0&&(P.path?A0[P.path]:A0);if(!A)continue;
    for(const [f,v] of Object.entries(P.set||{})){const b0=A[f];
      if(Array.isArray(v)&&Array.isArray(b0)&&v.length===2){const n0=Math.max(b0[0],Math.round(b0[0]+(v[0]-b0[0])*CAP6)),n1=Math.round(b0[1]+(v[1]-b0[1])*CAP6);sub(v[0]+'d'+v[1],n0+'d'+n1);P.set[f]=[n0,n1];continue;}
      if(typeof v!=='number'||typeof b0!=='number')continue;const int=Number.isInteger(v)&&Number.isInteger(b0);let n=b0+(v-b0)*CAP6;n=int?Math.round(n):Math.round(n*100)/100;if(n===v)continue;P.set[f]=n;
      if(v<1&&v>0&&!['cd','dur','T','stun','root','fuse'].includes(f))sub(Math.round(v*100)+'%',Math.round(n*100)+'%');
      else if(['cd','dur','T','stun','root','every','life'].includes(f))sub(fmtN(v,int)+'s',fmtN(n,int)+'s');
      else sub(fmtN(v,int),fmtN(n,int));}}
  if(N.stat){for(const f of ['hpPct','dmgPct','heal'])if(N.stat[f]){const v=N.stat[f],n=Math.round(v*CAP6);sub(v+'%',n+'%');N.stat[f]=n;}
    for(const [x,v] of Object.entries(N.stat.mod||{})){const n=Math.max(1,Math.round(v*CAP6));sub('+'+v,'+'+n);N.stat.mod[x]=n;}}
  N.txt=txt.replace(/\u0000(\d+)\u0000/g,(m,i)=>swaps[+i]);HCAP[k][L][nb]=N;return 'cap:'+L+':'+nb;}
/* 0.12.423 (Kyle): ability tooltips show the hero's own numbers after his talents (15% + a 5% talent shows 20%) */
const SEC_F=['cd','dur','T','stun','root','fuse','life','window','every','cast','slowT','markT','shieldT','high','soberAfter'];const PX_F=['r','range','rx','reach','depth'];
function abilDesc(k,H,id){const base=ABIL_DESC[id];if(typeof base!=='string'||!H)return base;let C1;try{C1=talChar(k,H);}catch(e){return base;}const C0=CHAR[k];if(!C1||C1===C0)return base;
  const A0=(C0.abilities||[]).find(a=>a.id===id),A1=(C1.abilities||[]).find(a=>a.id===id);if(!A0||!A1)return base;let txt=base,hit=0;
  const fm=(v,d)=>String(Math.round(v*Math.pow(10,d))/Math.pow(10,d));
  const sw=[];const sub=(from,to)=>{if(from===to)return;const i=txt.indexOf(from);if(i<0)return;txt=txt.slice(0,i)+'\u0001'+sw.length+'\u0001'+txt.slice(i+from.length);sw.push(to);hit++;};
  for(const f of Object.keys(A1)){const v0=A0[f],v1=A1[f];if(JSON.stringify(v0)===JSON.stringify(v1))continue;
    if(Array.isArray(v0)&&Array.isArray(v1)&&v0.length===2){sub(v0[0]+'d'+v0[1],v1[0]+'d'+v1[1]);continue;}
    if(typeof v0!=='number'||typeof v1!=='number')continue;
    if(f==='en')sub(v0+' energy',Math.round(v1)+' energy');
    else if(SEC_F.includes(f))sub(fm(v0,1)+'s',fm(v1,1)+'s');
    else if(PX_F.includes(f))sub(Math.round(v0*3)+'px',Math.round(v1*3)+'px');
    else if(v0>0&&v0<1){const p0=Math.round(v0*100);sub(`(${p0}% / ${p0*2}% / ${p0*3}%)`,`(${fm(v1*100,1)}% / ${fm(v1*200,1)}% / ${fm(v1*300,1)}%)`);sub(p0+'%',fm(v1*100,1)+'%');}
    else sub(String(v0),Number.isInteger(v0)?String(Math.round(v1)):fm(v1,2));}
  txt=txt.replace(/\u0001(\d+)\u0001/g,(m,i)=>sw[+i]);return hit?txt+' (numbers include talents)':base;}
function treeTalCard(k,tal){const [t,a,b]=tal.split(':');return t==='mod'?(TAL_MOD[k]||{})[a]:t==='cap'?((HCAP[k]&&HCAP[k][a]&&HCAP[k][a][b])||(TAL_CAP[a]&&TAL_CAP[a][b])):null;}
