const TREE_TNAME={seekyle:['Family','Culinary','Game Night'],edward:['Construction','Hard Worker','Friendship'],cheez:['Heritage','Steady Gaming','Casino Tech'],jp:['Gaming','Fishing','Smoking']};
const HERO_ORDER=Object.keys(TREE_SPEC);
