  const sup=`<div class="cc-card"><b>🏕️ Camp</b>${tent} <span class="cc-sub" style="font-size:12px">💰 <b style="color:#ffd23f">${fmt(gold)}</b> gold · ⚙️ <b>${parts}</b> spare parts · 🥫 <b>${Number.isInteger(food)?food:Math.floor(food)+'½'}</b> food · 💧 <b>${run.water||0}</b> water${Object.keys(MEDS).some(m=>(run.med||{})[m])?' · '+Object.keys(MEDS).filter(m=>(run.med||{})[m]).map(m=>`<span title="${esc(MEDS[m].name+': '+MEDS[m].txt)}" style="cursor:help">${MEDS[m].icon} <b>${run.med[m]}</b></span>`).join(' '):''} · <span title="Reroll dice (max 3): swap the camp upgrade offers or a hero's ⬆ Upgrade picks. Every stage you finish, won or lost, charges 25% of a die." style="cursor:help">${diceStr(run)}</span>${(s.lucky||0)?` · <span title="Lucky Dice: very rare loot. Spend one on a hero (button on their card) to gamble a basic attack's die size." style="cursor:help">${luckyStr(s)}</span>`:''}</span>${run.team.some(k=>missingOf(run,k)&&run.heroes[k]&&!run.heroes[k].dead)?` <button class="cc-btn" data-feedall style="padding:6px 16px;font-size:24px;vertical-align:middle" title="Feed and water everyone who needs it: most-needy and lowest HP first, never wastes supplies"><svg width="32" height="28" viewBox="0 0 16 14" style="vertical-align:-2px;image-rendering:pixelated"><rect x="1" y="5" width="7" height="8" fill="#b8642a"/><rect x="1" y="5" width="7" height="2" fill="#e8d0a0"/><rect x="2" y="8" width="5" height="3" fill="#e8302a"/><rect x="1" y="12" width="7" height="1" fill="#6a3a18"/><path d="M12 2 L14.5 7 A2.6 2.6 0 1 1 9.5 7 Z" fill="#4ab8ff"/><rect x="10.5" y="7" width="1" height="2" fill="#d8f4ff"/></svg> Feed all</button>`:''}
    ${(run.campLog||[]).length?`<div class="cc-sub" style="font-size:11px;margin:4px 0 0">${run.campLog.map(esc).join(' · ')}</div>`:''}
    ${run.eventLog?`<div class="cc-sub" style="font-size:12px;margin:6px 0 0;color:#ffd27a">${run.eventLog}</div>`:''}${run.evNext&&run.evNext.why&&run.evNext.why.length?`<div class="cc-sub" style="font-size:11px;margin:4px 0 0;color:#9ad0ff">⏭ Next stage: ${run.evNext.why.map(esc).join(' · ')}</div>`:''}${run.evPerm&&run.evPerm.why&&run.evPerm.why.length?`<div class="cc-sub" style="font-size:11px;margin:4px 0 0;color:#c8a0ff">♾ This run: ${run.evPerm.why.map(esc).join(' · ')}</div>`:''}
    ${owned.length?`<div class="cc-chips" style="margin-top:6px">${owned.map(id=>{const U=CAMP_UPG[id],t=run.upg[id];return `<span class="cc-chip" title="${esc(U.txt(t))}">${U.icon} ${esc(U.name)} ${['','I','II','III','IV'][t]}</span>`;}).join('')}</div>`:''}</div>`;
  const picked=run.picked||[];const offers=(run.offers||[]).filter(id=>picked.includes(id)||upgT(run,id)<CAMP_UPG[id].tiers.length);   /* 0.12.190 (Kyle): buy any or all of the 3 picks you can afford (each once per camp) */
  const up=`<div class="cc-card"><b>🔨 Camp upgrades</b> <span class="cc-sub" style="font-size:11px">${run.upgBought?`Buy any of the others you can still afford. New offers next camp.`:'Buy any or all of them you can afford, at the pick price.'} They last for this run.</span>${offers.length?(run.rerolls>=1?` <button class="cc-btn" data-reroll style="margin-left:6px;padding:2px 8px;font-size:11px" data-tipt="Spend 1 die: swap these 3 picks for 3 new ones. What you built stays built.">🎲 Reroll · ${diceStr(run)}</button>`:` <span class="cc-sub" style="font-size:11px;opacity:.7">${diceStr(run)}</span>`):''}
    <div class="cc-offers" style="margin-top:8px">${offers.map(id=>{const U=CAMP_UPG[id],t=upgT(run,id)+(picked.includes(id)?0:1),pr=upgPrice(run,id);return `<div class="cc-offer" style="--rc:${t>1?'#7fd0ff':'#a6ff2e'}"><span class="rar">${t>1?'TIER '+t:'NEW'}</span><span class="cn">${U.icon} ${esc(U.name)}${U.tiers.length>1?' '+['','I','II','III','IV'][t]:''}</span><span class="tx">${esc(U.txt(t))}</span>
      ${picked.includes(id)?`<button class="cc-btn" disabled>✓ Built</button>`:`<button class="cc-btn" data-upg="${id}" ${gold<pr?'disabled':''}>Build · ${fmt(pr)}g</button>${run.resource?`<button class="cc-btn" data-upgp="${id}" style="margin-top:4px" ${parts<upgParts(run,id)?'disabled':''}>Build · ⚙️ ${upgParts(run,id)} parts</button>`:''}`}</div>`;}).join('')||'<span class="cc-sub">Everything is fully built!</span>'}</div></div>`;
  const cl=conList(run);const con=`<div class="cc-card" style="border-color:#ffb020;box-shadow:0 0 0 1px #ffb02055,0 0 14px #ffb02033"><b>🏗️ Construction</b> <span class="cc-sub" style="font-size:11px">Build anything, as many as you like this camp, at <b>double</b> the pick price.</span>
    <button class="cc-btn" data-con style="margin-left:8px;background:#ffb020;color:#1a1000;font-weight:800">${run.conOpen?'▲ HIDE':'🏗️ OPEN CONSTRUCTION'}</button>
    ${run.conOpen?`<div class="cc-offers" style="margin-top:8px">${cl.map(id=>{const U=CAMP_UPG[id],t=upgT(run,id)+1,pr=conPrice(run,id);return `<div class="cc-offer" style="--rc:#ffb020"><span class="rar">${t>1?'TIER '+t:'NEW'}</span><span class="cn">${U.icon} ${esc(U.name)}${U.tiers.length>1?' '+['','I','II','III','IV'][t]:''}</span><span class="tx">${esc(U.txt(t))}</span>
      <button class="cc-btn" data-conb="${id}" ${gold<pr?'disabled':''}>Build · ${fmt(pr)}g</button>${run.resource?`<button class="cc-btn" data-conp="${id}" style="margin-top:4px" ${parts<conParts(run,id)?'disabled':''}>Build · ⚙️ ${conParts(run,id)} parts</button>`:''}</div>`;}).join('')||'<span class="cc-sub">Everything is fully built!</span>'}</div>`:''}</div>`;
  const tt=upgT(run,'triage');const tri=tt?`<div class="cc-card"><b>🩺 Triage Station ${['','I','II','III','IV'][tt]}</b> <span class="cc-sub" style="font-size:11px">${(run.triageN||0)}/${TRIAGE.max[tt-1]} built this camp · whoever you pick carries it into the next stage</span>
    ${[['med','Medkit','heals an ally under 50% for 35%'],['defib','Defibrillator','instantly revives a downed ally']].concat(run.team.includes('robot')?[['bat','Battery','+30 energy for the Warhound when he runs low']]:[]).map(([w,n,d])=>`<div class="cc-chips" style="align-items:center;margin-top:4px"><span class="cc-sub" style="font-size:11px;margin:0;min-width:180px"><b>${n}</b> · ⚙️ ${TRIAGE[w][tt-1]} · ${d}</span>${run.team.map(k=>btn(`data-tri="${w}|${k}" ${parts<TRIAGE[w][tt-1]||(run.triageN||0)>=TRIAGE.max[tt-1]?'disabled':''}`,'→ '+esc(heroDef(k).name.split(/[ _]/)[0]),'Build it for '+heroDef(k).name)).join(' ')}</div>`).join('')}
    <div class="cc-chips" style="align-items:center;margin-top:6px"><span class="cc-sub" style="font-size:11px;margin:0;min-width:180px"><b>Medical supplies</b> · go in the stash, no build limit</span>${Object.entries(MEDS).map(([m,M])=>btn(`data-medb="${m}" ${parts<M.parts?'disabled':''}`,`${M.icon} ${M.name} · ⚙️ ${M.parts}`,M.name+': '+M.txt)).join(' ')}</div></div>`:'';
  const tw=upgT(run,'tower');if(tw&&!run.scoutOffers)run.scoutOffers=scoutRoll(run);
  const tower=tw?`<div class="cc-card"><b>🗼 Watchtower ${['','I','II','III','IV'][tw]}</b> <span class="cc-sub" style="font-size:11px">Scouts report on the road ahead. ${tw>=4?'MAP TABLE: pick up to TWO roads for the next stage.':'Pick one for the next stage.'}</span>
    <div class="cc-offers" style="margin-top:8px">${(run.scoutOffers||[]).map(id=>{const S=SCOUT[id],on=[].concat(run.scoutPick||[]).includes(id);return `<div class="cc-offer" style="--rc:${on?'#a6ff2e':'#7fd0ff'}"><span class="cn">${S.icon} ${esc(S.name)}</span><span class="tx">${esc(S.txt(tw>=3?1.5:1))}</span><button class="cc-btn" data-scout="${id}" ${on&&tw<4?'disabled':''}>${on?(tw>=4?'Chosen ✓ (tap to drop)':'Chosen ✓'):'Take this road'}</button></div>`;}).join('')}</div></div>`:'';
  const rd=upgT(run,'radio');const radio=rd?(()=>{const F=radioForecast(run);return `<div class="cc-card"><b>📻 Radio Shack ${['','I','II'][rd]}</b> <span class="cc-sub" style="font-size:11px">Chatter about stage ${run.stage}: about <b>${F.foes}</b> undead in <b>${F.waves}</b> waves${F.wolves?' · 🐺 werewolves':''}${F.firemen?' · 🧑‍🚒 firemen':''}<br>🔋 Everyone starts the stage at full energy · first wave: ALERT (+10 accuracy)${rd>=2?' · ALERT on every wave · 📦 a supply drop halfway (food, water, 2 parts)':''}</span></div>`;})():'';   /* 0.12.105 */
  const stl=upgT(run,'still');const sF=[2,1.5,1,1][stl-1];const still=stl?`<div class="cc-card"><b>🫙 Moonshine Still ${['','I','II','III','IV'][stl]}</b> <span class="cc-sub" style="font-size:11px">A jar costs 🥫 ${sF} food + 💧 1 water, one for anyone you can afford · +20% damage, +10% attack speed, ${stl>=4?'15%':'10%'} less damage taken, ${stl>=4?'-15%':'-20%'} accuracy, steadier nerves until ${stl>=4?'the stage ends (going down no longer clears it)':stl===3?'they go down (50% chance it survives that) or the stage ends':'they go down or the stage ends'} (then pour another)</span>
    <div class="cc-chips" style="align-items:center;margin-top:4px">${run.team.filter(k=>k!=='robot').map(k=>(run.heroes[k].carry&&run.heroes[k].carry.courage)?`<span class="cc-chip" style="color:#ffd27a">🫙 ${esc(heroDef(k).name.split(/[ _]/)[0])} ✓ jar packed</span>`:btn(`data-brew="${k}" ${(run.food||0)<sF-1e-9||(run.water||0)<1?'disabled':''}`,'🫙 → '+esc(heroDef(k).name.split(/[ _]/)[0]),'Pour '+heroDef(k).name+' a jar: +20% damage, +10% attack speed, 10% less damage taken, -20% accuracy for the next stage')).join(' ')}</div></div>`:'';
