    const cell=({it,i})=>{const D=gearDef(it);const on=sel&&sel.where==='stash'&&sel.i===i;return `<div data-st="${i}" title="" style="width:52px;height:52px;display:flex;align-items:center;justify-content:center;cursor:pointer;border-radius:9px;background:#140c1c;border:2px solid ${GEAR_RAR[D.r].c}${on?'':'88'};${on?'box-shadow:0 0 10px '+GEAR_RAR[D.r].c+';':''}position:relative">${gearIcon(it,36)}${it.q===3?'<span style="position:absolute;top:1px;right:3px;font-size:9px">★</span>':it.q===2?'<span style="position:absolute;top:1px;right:3px;font-size:9px;color:#9ad8ff">✦</span>':''}</div>`;};
