    const act=ov.querySelector('[data-do="eq"]');if(act)act.onclick=()=>{if(gearEquip(s,k,sel.i)){sfx('level');persist();}sel=null;draw();};
    const un=ov.querySelector('[data-do="un"]');if(un)un.onclick=()=>{if(gearUnequip(s,k,sel.sl))persist();sel=null;draw();};
    const upb=ov.querySelector('[data-do="up"]');if(upb)upb.onclick=()=>{const it2=sel.where==='eq'?E[sel.sl]:G.stash[sel.i];if(gearUpgrade(s,it2)==='ok'){sfx('level');persist();}draw();};
