    {const sa=ov.querySelector('[data-sellall]');if(sa)sa.onclick=()=>{const R=gearSellTiers(s,s.sellTiers);if(R.n){sfx('heal');persist();}note=R.n?'Sold '+R.n+' item'+(R.n>1?'s':'')+' for '+R.gold+' 🪙':'Nothing to sell in those tiers';sel=null;draw();};}
    if(sel){const inf=ov.querySelector('[data-info]');if(inf&&inf.scrollIntoView)setTimeout(()=>inf.scrollIntoView({block:'nearest',behavior:'smooth'}),30);}   /* 0.12.414 (Kyle): tapping an item brings its buttons into view on phones */
